from __future__ import annotations

import pytest
from fastapi.testclient import TestClient

from app.config import get_settings
from app.llm.mock import MockLLMClient
from app.main import app
from app.schemas.detect import IndependentVerifierVerdict
from app.services.independent_verifiers import (
    build_multi_model_summary,
    evaluate_all_independent_verifiers,
    evaluate_single_verifier,
)


def _client() -> TestClient:
    return TestClient(app)


def test_gemma_is_fixed_answer_generator_ignoring_override() -> None:
    """Every question is generated by Gemma 4:26B; parameters cannot override it."""
    client = _client()
    for override_attempt in ["qwen", "gemini", "glm", "openrouter"]:
        resp = client.post(
            "/api/detect",
            json={"question": "What is the boiling point of water?", "answer_model": override_attempt},
        )
        assert resp.status_code == 200
        data = resp.json()
        assert data["answer_model"]["id"] == "gemma"
        assert data["answer_model"]["name"] == "Gemma 4:26B"
        assert data["base_answer"]["model"] == "Gemma 4:26B"

        # Verifier pool excludes Gemma and includes all other models
        verifier_ids = [v["id"] for v in data["verifiers"]]
        assert "gemma" not in verifier_ids
        for candidate in ["glm", "qwen", "openrouter", "phi"]:
            assert candidate in verifier_ids


@pytest.mark.asyncio
async def test_independent_verifiers_receive_context_and_return_structured_result() -> None:
    """Verifiers receive question, answer, claims, external evidence and return structured verdict."""
    mock_llm = MockLLMClient(scenario="reliable")
    settings = get_settings()

    verdict = await evaluate_single_verifier(
        "phi",
        question="What is the capital of Australia?",
        answer="Canberra is the capital of Australia.",
        settings=settings,
        test_llm=mock_llm,
        claims=["Canberra is Australia's capital."],
        web_evidence="Canberra was selected as the federal capital in 1908.",
    )

    assert verdict.model_id == "phi"
    assert verdict.model_name == "Phi-4 Reasoning"
    assert verdict.verdict in {"Correct", "Incorrect", "Uncertain"}
    assert verdict.status == "completed"
    assert verdict.reasoning != ""
    assert isinstance(verdict.contradictory_claims, list)
    assert verdict.confidence is not None
    assert 0.0 <= verdict.confidence <= 1.0


@pytest.mark.asyncio
async def test_all_independent_verifiers_evaluate_concurrently() -> None:
    """All non-Gemma models evaluate Gemma's answer concurrently."""
    mock_llm = MockLLMClient(scenario="reliable")
    settings = get_settings()

    verdicts = await evaluate_all_independent_verifiers(
        question="What is photosynthesis?",
        answer="Photosynthesis converts sunlight into chemical energy.",
        selected_answer_model_id="gemma",
        settings=settings,
        test_llm=mock_llm,
        claims=["Photosynthesis converts light energy into glucose."],
    )

    model_ids = {v.model_id for v in verdicts}
    assert model_ids == {"glm", "qwen", "openrouter", "phi"}
    assert "gemma" not in model_ids

    for v in verdicts:
        assert v.status == "completed"
        assert v.verdict == "Correct"


def test_multi_model_aggregation_consensus_and_disagreement() -> None:
    """Aggregation detects consensus, highlights disagreements, and handles failures."""
    # Consensus Correct
    verdicts_agree = [
        IndependentVerifierVerdict(model_id="gemini", model_name="Gemini Flash 3.8", provider="Google", verdict="Correct", reasoning="Accurate.", status="completed"),
        IndependentVerifierVerdict(model_id="glm", model_name="GLM-4.7-Flash", provider="Cloudflare", verdict="Correct", reasoning="Accurate.", status="completed"),
        IndependentVerifierVerdict(model_id="qwen", model_name="Qwen", provider="Groq", verdict="Correct", reasoning="Accurate.", status="completed"),
    ]
    summary_agree = build_multi_model_summary(verdicts_agree)
    assert summary_agree.agreement_state == "AGREEMENT"
    assert summary_agree.disagreements_detected is False
    assert summary_agree.correct_count == 3
    assert summary_agree.incorrect_count == 0

    # Disagreement: 2 Correct vs 1 Incorrect
    verdicts_disagree = [
        IndependentVerifierVerdict(model_id="gemini", model_name="Gemini Flash 3.8", provider="Google", verdict="Correct", reasoning="Accurate.", status="completed"),
        IndependentVerifierVerdict(model_id="glm", model_name="GLM-4.7-Flash", provider="Cloudflare", verdict="Correct", reasoning="Accurate.", status="completed"),
        IndependentVerifierVerdict(model_id="qwen", model_name="Qwen", provider="Groq", verdict="Incorrect", reasoning="Wrong date.", contradictory_claims=["Claimed year is 1999."], status="completed"),
    ]
    summary_disagree = build_multi_model_summary(verdicts_disagree)
    assert summary_disagree.agreement_state == "DISAGREEMENT"
    assert summary_disagree.disagreements_detected is True
    assert summary_disagree.correct_count == 2
    assert summary_disagree.incorrect_count == 1
    assert "Claimed year is 1999." in summary_disagree.contradictory_claims

    # Failure isolation: 1 failed does not invalidate the other 2
    verdicts_failed = [
        IndependentVerifierVerdict(model_id="gemini", model_name="Gemini Flash 3.8", provider="Google", verdict="Correct", reasoning="Accurate.", status="completed"),
        IndependentVerifierVerdict(model_id="glm", model_name="GLM-4.7-Flash", provider="Cloudflare", verdict="FAILED", error="HTTP 429", status="failed"),
    ]
    summary_failed = build_multi_model_summary(verdicts_failed)
    assert summary_failed.correct_count == 1
    assert summary_failed.failed_count == 1
    assert summary_failed.completed_verifiers == 1


def test_api_detect_flow_returns_ai_verdicts_and_multi_model_summary() -> None:
    """The detect endpoint returns Gemma answer, ai_verdicts, and multi_model_summary."""
    client = _client()
    resp = client.post("/api/detect", json={"question": "What is the speed of light?"})
    assert resp.status_code == 200
    data = resp.json()

    assert data["base_answer"]["model"] == "Gemma 4:26B"
    assert data["answer_model"]["id"] == "gemma"
    assert "ai_verdicts" in data
    assert len(data["ai_verdicts"]) == 4
    for v in data["ai_verdicts"]:
        assert v["model_id"] in {"glm", "qwen", "openrouter", "phi"}

    assert "multi_model_summary" in data
    assert data["multi_model_summary"] is not None
    assert data["multi_model_summary"]["total_verifiers"] == 4
